    """
    Implements a recursive backtracking algorithm to perform regex matching.
    Supports literal characters, '.', '*' (zero or more of the preceding), 
    and '+' (one or more of the preceding).
    """

    def is_match(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx == len(pattern):
            return False

        current_match = (t_idx < len(text)) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.')

        if p_idx + 1 < len(pattern):
            if pattern[p_idx + 1] == '*':
                return (is_match(p_idx + 2, t_idx) or 
                        (current_match and is_match(p_idx, t_idx + 1)))
            elif pattern[p_idx + 1] == '+':
                if current_match:
                    return (is_match(p_idx, t_idx + 1) or 
                            is_match(p_idx + 2, t_idx))
                else:
